use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{fs,path::Path,collections::BTreeMap};
const R:&str="/home/ubuntu/src/zopro-perf-work/crt-euler-direct176";
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn main(){let mut pins:BTreeMap<String,String>=serde_json::from_slice(&fs::read(format!("{R}/pins.json")).unwrap()).unwrap();for(p,h)in&pins{assert_eq!(hash(p),*h);}let source=fs::read_to_string(format!("{R}/direct.rs")).unwrap();assert_eq!(source.matches("BigInt::from(&m)").count(),1);fs::write(format!("{R}/direct-fixed.rs"),source.replace("BigInt::from(&m)","BigInt::from(m.clone())")).unwrap();let base=fs::read_to_string(format!("{R}/base.rs")).unwrap();assert_eq!(base.matches("#[path=\"direct.rs\"]").count(),1);fs::write(format!("{R}/base-fixed.rs"),base.replace("#[path=\"direct.rs\"]","#[path=\"direct-fixed.rs\"]")).unwrap();let driver=fs::read_to_string(format!("{R}/driver.rs")).unwrap();fs::write(format!("{R}/driver-fixed.rs"),driver.replace("#[path=\"base.rs\"]","#[path=\"base-fixed.rs\"]")).unwrap();let mut plan:Value=serde_json::from_slice(&fs::read(format!("{R}/plan.json")).unwrap()).unwrap();for step in plan["steps"].as_array_mut().unwrap(){for arg in step["argv"].as_array_mut().unwrap(){if arg==&json!(format!("{R}/base.rs")){*arg=json!(format!("{R}/base-fixed.rs"));}else if arg==&json!(format!("{R}/driver.rs")){*arg=json!(format!("{R}/driver-fixed.rs"));}}}for f in["direct-fixed.rs","base-fixed.rs","driver-fixed.rs","repair-test.rs","repair-test","pins.json","plan.json","runs/compile-direct-tests/exit.json","runs/compile-direct-tests/stderr.log"]{let p=format!("{R}/{f}");pins.insert(p.clone(),hash(p));}fs::write(format!("{R}/pins-fixed.json"),serde_json::to_vec_pretty(&pins).unwrap()).unwrap();plan["source_pins"]=json!(format!("{R}/pins-fixed.json"));fs::write(format!("{R}/plan-fixed.json"),serde_json::to_vec_pretty(&plan).unwrap()).unwrap();println!("Fixedone test-only BigInt ownership conversion;runtime sourceprefix byteexact;all previous pinsclose;no testexecutedbeforefailure");}
